24: const FIELD_TYPES: readonly FormFieldType[] = ['text', 'number', 'select', 'date', 'checkbox'];
25: const SECTIONS: readonly FormFieldSection[] = ['policyholder', 'vehicle'];
26: const RULES: readonly string[] = [
