39: /** The only place that builds Strapi URLs and appends the country filter. */
40: @Injectable({ providedIn: 'root' })
41: export class CatalogueApi {
42:   private readonly http = inject(HttpClient);
43:   private readonly apiBaseUrl = inject(API_BASE_URL);
44: 
45:   getFormFields(country: CountryCode): Observable<readonly FormFieldConfig[]> {
46:     const url =
47:       `${this.apiBaseUrl}/api/form-fields?filters[country][$eq]=${country}` +
48:       '&sort=order:asc&pagination[pageSize]=100';
49: 
50:     return this.http
51:       .get<StrapiListResponse<unknown>>(url)
52:       .pipe(map((response) => this.mapFields(response, country)));
53:   }
54: 
55:   getCountryConfig(country: CountryCode): Observable<CountryConfig | null> {
56:     const url = `${this.apiBaseUrl}/api/country-configs?filters[country][$eq]=${country}`;
57:     return this.http
58:       .get<StrapiListResponse<unknown>>(url)
59:       .pipe(map((response) => this.mapCountryConfig(response, country)));
60:   }
61: 
62:   getInsurancePlans(country: CountryCode): Observable<readonly InsurancePlan[]> {
63:     const url =
64:       `${this.apiBaseUrl}/api/insurance-plans?filters[country][$eq]=${country}` +
65:       '&filters[active][$eq]=true&sort=order:asc&pagination[pageSize]=100';
66: 
67:     return this.http
68:       .get<StrapiListResponse<unknown>>(url)
69:       .pipe(map((response) => this.mapPlans(response, country)));
70:   }
71: 
72:   private mapPlans(
73:     response: StrapiListResponse<unknown>,
74:     country: CountryCode,
75:   ): readonly InsurancePlan[] {
76:     const rows = Array.isArray(response.data) ? response.data : [];
77:     const pagination = response.meta?.pagination;
78:     if (pagination && pagination.total > rows.length && isDevMode()) {
79:       console.warn(
80:         `[catalogue] only ${rows.length} of ${pagination.total} plans for ${country} were received (page size 100).`,
81:       );
82:     }
83: 
84:     const mapped: InsurancePlan[] = [];
85:     for (const row of rows) {
86:       const plan = this.toInsurancePlan(row, country);
87:       if (plan) {
88:         mapped.push(plan);
89:       }
90:     }
91: 
92:     // Deduplicate by documentId keeping the lowest numeric id before final display sorting.
93:     mapped.sort((left, right) => left.id - right.id);
94:     const byDocumentId = new Map<string, InsurancePlan>();
95:     for (const plan of mapped) {
96:       const existing = byDocumentId.get(plan.documentId);
97:       if (existing) {
98:         if (isDevMode()) {
99:           console.warn(
100:             `[catalogue] duplicate plan documentId "${plan.documentId}"; keeping id ${existing.id}.`,
101:           );
102:         }
103:         continue;
104:       }
105:       byDocumentId.set(plan.documentId, plan);
106:     }
107: 
108:     return [...byDocumentId.values()].sort(
109:       (left, right) => left.order - right.order || left.id - right.id,
110:     );
111:   }
112: 
113:   private toInsurancePlan(raw: unknown, country: CountryCode): InsurancePlan | null {
114:     if (!isRecord(raw)) {
115:       this.warnInvalidPlan('non-object row');
116:       return null;
117:     }
118: 
119:     const id = raw['id'];
120:     const documentId = raw['documentId'];
121:     const key = raw['key'];
122:     const name = raw['name'];
123:     const shortDescription = raw['shortDescription'];
124:     const rawPrice = raw['basePrice'];
125:     const currency = raw['currency'];
126:     const order = raw['order'];
127:     const active = raw['active'];
128:     const rowCountry = raw['country'];
129:     const recommended = raw['recommended'];
130: 
131:     if (
132:       typeof id !== 'number' ||
133:       !Number.isFinite(id) ||
134:       typeof documentId !== 'string' ||
135:       documentId.trim().length === 0 ||
136:       typeof key !== 'string' ||
137:       key.trim().length === 0 ||
138:       typeof order !== 'number' ||
139:       !Number.isFinite(order)
140:     ) {
141:       this.warnInvalidPlan('missing or malformed required attributes');
142:       return null;
143:     }
144: 
145:     if (active !== true) {
146:       this.warnInvalidPlan(`inactive plan "${key}"`);
147:       return null;
148:     }
149:     if (rowCountry !== country) {
150:       this.warnInvalidPlan(`plan "${key}" from country ${String(rowCountry)} in ${country} response`);
151:       return null;
152:     }
153: 
154:     const hasPrice =
155:       typeof rawPrice === 'number' ||
156:       (typeof rawPrice === 'string' && rawPrice.trim().length > 0);
157:     const basePrice = hasPrice ? Number(rawPrice) : Number.NaN;
158:     if (!Number.isFinite(basePrice) || !Number.isInteger(basePrice) || basePrice < 0) {
159:       this.warnInvalidPlan(`invalid basePrice on plan "${key}"`);
160:       return null;
161:     }
162: 
163:     const expectedCurrency = COUNTRY_CATALOG_BY_CODE[country].currency;
164:     if (currency !== expectedCurrency) {
165:       this.warnInvalidPlan(`currency mismatch on plan "${key}"`);
166:       return null;
167:     }
168: 
169:     return {
170:       id,
171:       documentId,
172:       key,
173:       name: typeof name === 'string' && name.length > 0 ? name : key,
174:       shortDescription: typeof shortDescription === 'string' ? shortDescription : '',
175:       basePrice,
176:       currency: expectedCurrency as CurrencyCode,
177:       coverages: this.parseCoverages(raw['coverages'], key),
178:       benefits: this.parseBenefits(raw['benefits'], key),
179:       order,
180:       recommended: recommended === true,
181:       country,
182:     };
183:   }
184: 
185:   private parseCoverages(raw: unknown, planKey: string): readonly PlanCoverageItem[] {
186:     if (!Array.isArray(raw)) {
187:       if (raw !== null && raw !== undefined && isDevMode()) {
188:         console.warn(`[catalogue] dropping malformed coverages on plan "${planKey}".`);
189:       }
190:       return [];
191:     }
192: 
193:     const coverages: PlanCoverageItem[] = [];
194:     for (const entry of raw) {
195:       if (
196:         !isRecord(entry) ||
197:         typeof entry['name'] !== 'string' ||
198:         entry['name'].trim().length === 0 ||
199:         typeof entry['limit'] !== 'number' ||
200:         !Number.isFinite(entry['limit'])
201:       ) {
202:         if (isDevMode()) {
203:           console.warn(`[catalogue] dropping malformed coverage on plan "${planKey}".`);
204:         }
205:         continue;
206:       }
207: 
208:       const rawDeductible = entry['deductible'];
209:       const deductible =
210:         rawDeductible === null || rawDeductible === undefined
211:           ? null
212:           : typeof rawDeductible === 'number' && Number.isFinite(rawDeductible)
213:             ? rawDeductible
214:             : null;
215:       coverages.push({ name: entry['name'], limit: entry['limit'], deductible });
216:     }
217:     return coverages;
218:   }
219: 
220:   private parseBenefits(raw: unknown, planKey: string): readonly string[] {
221:     if (!Array.isArray(raw)) {
222:       if (raw !== null && raw !== undefined && isDevMode()) {
223:         console.warn(`[catalogue] dropping malformed benefits on plan "${planKey}".`);
224:       }
225:       return [];
226:     }
227: 
228:     const benefits: string[] = [];
229:     for (const entry of raw) {
230:       if (typeof entry === 'string') {
231:         benefits.push(entry);
232:       } else if (isDevMode()) {
233:         console.warn(`[catalogue] dropping malformed benefit on plan "${planKey}".`);
234:       }
235:     }
236:     return benefits;
237:   }
238: 
239:   private mapFields(
240:     response: StrapiListResponse<unknown>,
241:     country: CountryCode,
242:   ): readonly FormFieldConfig[] {
243:     const rows = Array.isArray(response.data) ? response.data : [];
244:     const pagination = response.meta?.pagination;
245:     if (pagination && pagination.total > rows.length && isDevMode()) {
246:       console.warn(
247:         `[catalogue] only ${rows.length} of ${pagination.total} fields for ${country} were received (page size 100).`,
248:       );
249:     }
250: 
251:     const mapped: FormFieldConfig[] = [];
252:     for (const row of rows) {
253:       const field = this.toFormFieldConfig(row, country);
254:       if (field) {
255:         mapped.push(field);
256:       }
257:     }
258: 
259:     // De-duplicate by key keeping the lowest order (tie-break by lowest id), then apply rendering order.
260:     mapped.sort(
261:       (left, right) =>
262:         left.key.localeCompare(right.key) || left.order - right.order || left.id - right.id,
263:     );
264:     const byKey = new Map<string, FormFieldConfig>();
265:     for (const field of mapped) {
266:       const existing = byKey.get(field.key);
267:       if (existing && existing.id !== field.id && isDevMode()) {
268:         console.warn(
269:           `[catalogue] duplicate field key "${field.key}"; keeping order ${existing.order} (id ${existing.id}).`,
270:         );
271:       }
272:       if (!existing) {
273:         byKey.set(field.key, field);
274:       }
275:     }
276: 
277:     return [...byKey.values()].sort((left, right) => left.order - right.order || left.id - right.id);
278:   }
279: 
280:   private toFormFieldConfig(raw: unknown, country: CountryCode): FormFieldConfig | null {
281:     if (!isRecord(raw)) {
282:       this.warnInvalid('non-object row');
283:       return null;
284:     }
285: 
286:     const id = raw['id'];
287:     const documentId = raw['documentId'];
288:     const key = raw['key'];
289:     const label = raw['label'];
290:     const type = raw['type'];
291:     const required = raw['required'];
292:     const order = raw['order'];
293:     const section = raw['section'];
294:     const rowCountry = raw['country'];
295: 
296:     if (
297:       typeof id !== 'number' ||
298:       typeof documentId !== 'string' ||
299:       typeof key !== 'string' ||
300:       !/^[a-zA-Z][a-zA-Z0-9]*$/.test(key) ||
301:       typeof label !== 'string' ||
302:       typeof type !== 'string' ||
303:       !FIELD_TYPES.includes(type as FormFieldType) ||
304:       typeof required !== 'boolean' ||
305:       typeof order !== 'number'
306:     ) {
307:       this.warnInvalid('missing or malformed required attributes');
308:       return null;
309:     }
310: 
311:     if (typeof rowCountry === 'string' && rowCountry !== country) {
312:       if (isDevMode()) {
313:         console.warn(`[catalogue] dropping field "${key}" from country ${rowCountry} in ${country} response.`);
314:       }
315:       return null;
316:     }
317: 
318:     const fieldType = type as FormFieldType;
319:     const fieldSection: FormFieldSection =
320:       typeof section === 'string' && SECTIONS.includes(section as FormFieldSection)
321:         ? (section as FormFieldSection)
322:         : 'policyholder';
323: 
324:     return {
325:       id,
326:       documentId,
327:       key,
328:       label,
329:       type: fieldType,
330:       required,
331:       validations: this.parseValidations(raw['validations'], key),
332:       options: this.parseOptions(raw['options'], key),
333:       helpText: this.parseNullableString(raw['helpText']),
334:       errorMessage: this.parseNullableString(raw['errorMessage']),
335:       order,
336:       country,
337:       section: fieldSection,
338:     };
339:   }
340: 
341:   private parseValidations(raw: unknown, fieldKey: string): FormFieldValidationRules {
342:     if (!isRecord(raw)) {
343:       return {};
344:     }
345: 
346:     const rules: MutableValidations = {};
347:     const minLength = raw['minLength'];
348:     const maxLength = raw['maxLength'];
349:     const min = raw['min'];
350:     const max = raw['max'];
351:     if (typeof minLength === 'number' && Number.isFinite(minLength)) {
352:       rules.minLength = minLength;
353:     }
354:     if (typeof maxLength === 'number' && Number.isFinite(maxLength)) {
355:       rules.maxLength = maxLength;
356:     }
357:     if (typeof min === 'number' && Number.isFinite(min)) {
358:       rules.min = min;
359:     }
360:     if (typeof max === 'number' && Number.isFinite(max)) {
361:       rules.max = max;
362:     }
363: 
364:     const minDate = raw['minDate'];
365:     const maxDate = raw['maxDate'];
366:     if (typeof minDate === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(minDate)) {
367:       rules.minDate = minDate;
368:     }
369:     if (typeof maxDate === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(maxDate)) {
370:       rules.maxDate = maxDate;
371:     }
372: 
373:     const pattern = raw['pattern'];
374:     if (typeof pattern === 'string' && pattern.length > 0) {
375:       rules.pattern = pattern;
376:     }
377:     const integer = raw['integer'];
378:     if (typeof integer === 'boolean') {
379:       rules.integer = integer;
380:     }
381:     const transform = raw['transform'];
382:     if (transform === 'uppercase' || transform === 'trim') {
383:       rules.transform = transform;
384:     }
385:     const rule = raw['rule'];
386:     if (typeof rule === 'string' && RULES.includes(rule)) {
387:       rules.rule = rule as FormFieldValidationRules['rule'];
388:     }
389: 
390:     if (isDevMode()) {
391:       for (const key of Object.keys(raw)) {
392:         if (!(key in rules)) {
393:           console.warn(`[catalogue] ignoring unknown validation "${key}" on field "${fieldKey}".`);
394:         }
395:       }
396:     }
397:     return rules;
398:   }
399: 
400:   private parseOptions(raw: unknown, fieldKey: string): readonly FormFieldOption[] {
401:     if (!Array.isArray(raw)) {
402:       return [];
403:     }
404: 
405:     const options: FormFieldOption[] = [];
406:     for (const entry of raw) {
407:       if (
408:         isRecord(entry) &&
409:         typeof entry['value'] === 'string' &&
410:         typeof entry['label'] === 'string'
411:       ) {
412:         options.push({ value: entry['value'], label: entry['label'] });
413:       } else if (isDevMode()) {
414:         console.warn(`[catalogue] dropping malformed option on field "${fieldKey}".`);
415:       }
416:     }
417:     return options;
418:   }
